<?php
require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:(isset($_POST['sesi_id'])?(int)$_POST['sesi_id']:0);$stmt=$pdo->prepare('SELECT * FROM absensi_sesi WHERE id=?');$stmt->execute([$id]);$session=$stmt->fetch();if(!$session){osis_set_flash('error','Sesi absensi tidak ditemukan.');osis_redirect('admin/absensi/index.php');}$pageTitle='Isi absensi';$error='';$validStatuses=['hadir','izin','sakit','alpa'];
if(osis_admin_is_post()){osis_verify_csrf();$statuses=isset($_POST['status'])&&is_array($_POST['status'])?$_POST['status']:[];$notes=isset($_POST['keterangan'])&&is_array($_POST['keterangan'])?$_POST['keterangan']:[];try{$pdo->beginTransaction();$upsert=$pdo->prepare('INSERT INTO absensi(sesi_id,anggota_id,status,keterangan,dicatat_oleh) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),keterangan=VALUES(keterangan),dicatat_oleh=VALUES(dicatat_oleh)');$members=$pdo->query('SELECT id FROM anggota WHERE status=\'aktif\'')->fetchAll();foreach($members as $member){$memberId=(int)$member['id'];$status=isset($statuses[$memberId])?(string)$statuses[$memberId]:'alpa';if(!in_array($status,$validStatuses,true)){$status='alpa';}$note=isset($notes[$memberId])?trim((string)$notes[$memberId]):'';$upsert->execute([$id,$memberId,$status,$note!==''?mb_substr($note,0,220,'UTF-8'):null,osis_current_user()['id']]);}$pdo->commit();osis_log_activity('Mengisi absensi untuk sesi: '.$session['judul']);osis_set_flash('success','Rekap kehadiran berhasil disimpan.');osis_redirect('admin/absensi/isi.php?id='.$id);}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error='Absensi gagal disimpan. Coba kembali.';}}
$stmt=$pdo->prepare("SELECT a.id,a.nama,a.kelas,a.nis,ab.status AS absen_status,ab.keterangan AS absen_keterangan FROM anggota a LEFT JOIN absensi ab ON ab.anggota_id=a.id AND ab.sesi_id=? WHERE a.status='aktif' ORDER BY a.kelas,a.nama");$stmt->execute([$id]);$members=$stmt->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="attendance-page-heading"><a class="back-link" href="<?=osis_e(osis_url('admin/absensi/index.php'))?>">← Semua sesi</a><div><span class="eyebrow">SESI · <?=osis_e(osis_format_date($session['tanggal']))?></span><h2><?=osis_e($session['judul'])?></h2><p><?=osis_e($session['keterangan']?:'Pilih status kehadiran untuk setiap anggota.')?></p></div></div><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" class="admin-panel attendance-form"><?=osis_csrf_input()?><input type="hidden" name="sesi_id" value="<?=$id?>"><div class="attendance-form-toolbar"><span><strong><?=count($members)?></strong> anggota aktif</span><button type="button" class="button button-outline button-small" data-mark-all-present>Tandai semua hadir</button></div><div class="table-scroll"><table class="data-table attendance-table"><thead><tr><th>Anggota</th><th>Status kehadiran</th><th>Keterangan</th></tr></thead><tbody><?php if($members):foreach($members as $member):$current=isset($_POST['status'][$member['id']])?$_POST['status'][$member['id']]:($member['absen_status']?:'alpa');?><tr><td><strong><?=osis_e($member['nama'])?></strong><small class="table-subtext"><?=osis_e(trim(($member['kelas']?:'').' · '.($member['nis']?:''),' ·'))?></small></td><td><select class="attendance-status-select" name="status[<?=(int)$member['id']?>]"><?php foreach($validStatuses as $status):?><option value="<?=osis_e($status)?>" <?=$current===$status?'selected':''?>><?=osis_e(ucfirst($status))?></option><?php endforeach;?></select></td><td><input class="attendance-note" name="keterangan[<?=(int)$member['id']?>]" maxlength="220" placeholder="Opsional" value="<?=osis_e(isset($_POST['keterangan'][$member['id']])?$_POST['keterangan'][$member['id']]:$member['absen_keterangan'])?>"></td></tr><?php endforeach;else:?><tr><td colspan="3" class="empty-inline">Belum ada anggota aktif untuk dicatat.</td></tr><?php endif;?></tbody></table></div><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/absensi/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan absensi <span>↗</span></button></div></form>
<?php osis_admin_page_end(); ?>
